import { relations } from "drizzle-orm";
import {
  bigint,
  boolean,
  date,
  index,
  integer,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

import { ASSET_KINDS, TXN_KINDS } from "~/lib/portfolio";

/* -------------------------------------------------------------------------- */
/*  Auth tables (generated by `npx auth generate`; do not edit by hand)        */
/* -------------------------------------------------------------------------- */

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

export const rateLimit = pgTable("rate_limit", {
  id: text("id").primaryKey(),
  key: text("key").notNull().unique(),
  count: integer("count").notNull(),
  lastRequest: bigint("last_request", { mode: "number" }).notNull(),
});

export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
}));

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, {
    fields: [session.userId],
    references: [user.id],
  }),
}));

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, {
    fields: [account.userId],
    references: [user.id],
  }),
}));

/* -------------------------------------------------------------------------- */
/*  App tables                                                                 */
/* -------------------------------------------------------------------------- */

const money = (name: string) =>
  numeric(name, { precision: 18, scale: 2, mode: "number" });
/** Units and unit prices: fund NAVs carry four decimals. */
const quantity = (name: string) =>
  numeric(name, { precision: 18, scale: 4, mode: "number" });
/** Plain calendar date in Pakistan time, "YYYY-MM-DD". */
const day = (name: string) => date(name, { mode: "string" });
const ownerId = () =>
  text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" });
const createdAt = () => timestamp("created_at").defaultNow().notNull();

export const assetKind = pgEnum("asset_kind", ASSET_KINDS);
export const txnKind = pgEnum("txn_kind", TXN_KINDS);
export const priceSource = pgEnum("price_source", ["auto", "manual"]);
export const billingCycle = pgEnum("billing_cycle", ["monthly", "yearly"]);
export const subscriptionStatus = pgEnum("subscription_status", [
  "active",
  "paused",
]);

/** One row per holding or account. */
export const asset = pgTable(
  "asset",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    userId: ownerId(),
    kind: assetKind("kind").notNull(),
    name: text("name").notNull(),
    /** PSX ticker (stocks only). */
    symbol: text("symbol"),
    /** MUFAP fund id (funds only). */
    fundId: text("fund_id"),
    /** Broker, asset manager or bank. */
    institution: text("institution"),
    /** Fund category, e.g. "Money Market". */
    category: text("category"),
    lastPrice: quantity("last_price"),
    priceAsOf: day("price_as_of"),
    priceSource: priceSource("price_source"),
    priceCheckedAt: timestamp("price_checked_at"),
    /** Savings: annual profit rate in percent, display only. */
    profitRate: numeric("profit_rate", {
      precision: 5,
      scale: 2,
      mode: "number",
    }),
    notes: text("notes"),
    createdAt: createdAt(),
  },
  (t) => [index("asset_user_kind_idx").on(t.userId, t.kind)],
);

/** Every movement in a holding or account. */
export const assetTxn = pgTable(
  "asset_txn",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    userId: ownerId(),
    assetId: integer("asset_id")
      .notNull()
      .references(() => asset.id, { onDelete: "cascade" }),
    kind: txnKind("kind").notNull(),
    date: day("date").notNull(),
    units: quantity("units"),
    unitPrice: quantity("unit_price"),
    /** Gross PKR. units × price for buy/sell, cash for the rest, 0 for bonus. */
    amount: money("amount").notNull(),
    fees: money("fees").notNull().default(0),
    notes: text("notes"),
    createdAt: createdAt(),
  },
  (t) => [index("asset_txn_asset_date_idx").on(t.assetId, t.date)],
);

/** Daily totals per asset kind, written by the daily job. */
export const portfolioSnapshot = pgTable(
  "portfolio_snapshot",
  {
    userId: ownerId(),
    date: day("date").notNull(),
    kind: assetKind("kind").notNull(),
    marketValue: money("market_value").notNull(),
    costBasis: money("cost_basis").notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.date, t.kind] })],
);

export const expenseCategory = pgTable(
  "expense_category",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    userId: ownerId(),
    name: text("name").notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("expense_category_user_name_idx").on(t.userId, t.name)],
);

export const subscription = pgTable(
  "subscription",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    userId: ownerId(),
    name: text("name").notNull(),
    amount: money("amount").notNull(),
    categoryId: integer("category_id")
      .notNull()
      .references(() => expenseCategory.id, { onDelete: "restrict" }),
    cycle: billingCycle("cycle").notNull(),
    nextDueDate: day("next_due_date").notNull(),
    /** Day of the month the plan is anchored to, so the 31st does not drift. */
    billingDay: integer("billing_day").notNull(),
    status: subscriptionStatus("status").notNull().default("active"),
    notes: text("notes"),
    createdAt: createdAt(),
  },
  (t) => [index("subscription_user_status_idx").on(t.userId, t.status)],
);

export const expense = pgTable(
  "expense",
  {
    id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
    userId: ownerId(),
    date: day("date").notNull(),
    amount: money("amount").notNull(),
    categoryId: integer("category_id")
      .notNull()
      .references(() => expenseCategory.id, { onDelete: "restrict" }),
    title: text("title").notNull(),
    notes: text("notes"),
    /** Set when the expense was created by "Mark paid". */
    subscriptionId: integer("subscription_id").references(
      () => subscription.id,
      { onDelete: "set null" },
    ),
    createdAt: createdAt(),
  },
  (t) => [index("expense_user_date_idx").on(t.userId, t.date)],
);

export const assetRelations = relations(asset, ({ many }) => ({
  txns: many(assetTxn),
}));

export const assetTxnRelations = relations(assetTxn, ({ one }) => ({
  asset: one(asset, { fields: [assetTxn.assetId], references: [asset.id] }),
}));

export const expenseRelations = relations(expense, ({ one }) => ({
  category: one(expenseCategory, {
    fields: [expense.categoryId],
    references: [expenseCategory.id],
  }),
  subscription: one(subscription, {
    fields: [expense.subscriptionId],
    references: [subscription.id],
  }),
}));

export const subscriptionRelations = relations(subscription, ({ one }) => ({
  category: one(expenseCategory, {
    fields: [subscription.categoryId],
    references: [expenseCategory.id],
  }),
}));

export type Asset = typeof asset.$inferSelect;
export type AssetTxn = typeof assetTxn.$inferSelect;
export type Expense = typeof expense.$inferSelect;
export type ExpenseCategory = typeof expenseCategory.$inferSelect;
export type Subscription = typeof subscription.$inferSelect;
